package com.amdocs.telecom.util;
import java.sql.*; import java.nio.file.*; import java.io.*;
public final class DBConnection { private static final DBConnection INSTANCE=new DBConnection(); private DBConnection(){} public static DBConnection getInstance(){return INSTANCE;} public Connection get() throws SQLException {return DriverManager.getConnection(env("DB_URL","jdbc:h2:./data/tsatms"),env("DB_USER","sa"),env("DB_PASSWORD",""));} public void init(){try(Connection c=get(); Statement s=c.createStatement()){String sql=new String(Files.readAllBytes(Paths.get("database/schema.sql")),"UTF-8"); for(String q:sql.split(";"))if(!q.trim().isEmpty())s.execute(q);}catch(Exception e){throw new RuntimeException("Database initialization failed",e);}} public static String env(String k,String d){String v=System.getenv(k);return v==null||v.trim().isEmpty()?d:v;} }
